      ? DynamicLibrary.open('libfastdev_quickjs_runtime.so')
      : DynamicLibrary.open(
          Platform.environment['LIBQUICKJSC_TEST_PATH'] ??
              'libquickjs_c_bridge_plugin.so',
        );
  lib.lookup<NativeFunction<Void Function()>>('jsNewRuntime');
  return true;
}

